{
  "definition_simple": "没有限量，无法计算，多形容前途、功德或潜力极大。",
  "definition_standard": "无法计量；没有限度。多用作定语或谓语，常用于“前途无量”、“功德无量”等固定搭配中，表示极其广大、不可限量。",
  "pos": "形容词",
  "semantic_class": "property",
  "sentences": [
    {
      "text": "小明学习非常刻苦，老师夸他前途无量。",
      "tier": "T1"
    },
    {
      "text": "年轻人勇于拼搏，未来的发展潜力无量。",
      "tier": "T2"
    },
    {
      "text": "修建这所希望小学是一件功德无量的大善事。",
      "tier": "T2"
    },
    {
      "text": "这项新能源技术一旦研发成功，市场价值不可估量、商机无量。",
      "tier": "T3"
    },
    {
      "text": "佛家常说慈悲心能广积善缘，所得福报亦是无量无边。",
      "tier": "T3"
    },
    {
      "text": "宇宙浩瀚，繁星如海，其中蕴含着无量的奥秘等待人类去探寻。",
      "tier": "T4"
    },
    {
      "text": "科研团队历经数载攻克技术壁垒，此项突破对国家工业升级贡献无量。",
      "tier": "T4"
    },
    {
      "text": "先生毕生致力于古籍整理与抢救，虽甘于寂寞，然其学术泽被后世，实属功德无量。",
      "tier": "T5"
    },
    {
      "text": "大乘经典有云：应发无量心，誓度无量众生，以无边愿力铸就解脱之途。",
      "tier": "T5"
    },
    {
      "text": "观夫天地化生，气机流转，其生生不息之生机与造化伟力，诚浩瀚而无量也。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "无良",
      "explanation": "拼音同为 wúliáng，声调完全相同，但“无良”意为没有良心、不道德，常用于“无良商家”，与褒义/中性的“无量”极易在听觉上混淆。"
    },
    {
      "word": "无粮",
      "explanation": "拼音同为 wúliáng，意为没有粮食，语境和词义截然不同，同音极易引起听觉歧义。"
    },
    {
      "word": "物价",
      "explanation": "拼音为 wùjià，声韵母差异较明显，但在方言区或语速极快时声韵容易与 wúliàng 产生听感混淆。"
    }
  ],
  "primary_collocate": "前途无量",
  "collocation_distractors": [
    {
      "word": "广大",
      "explanation": "“广大”常修饰空间、规模或群众（如“广大人民”），与“无量”语义重叠但语法功能不搭配，不可组合成“广大无量”。"
    },
    {
      "word": "很多",
      "explanation": "“很多”为口语中表示数量多的常用词，属于口语初级词汇，与书面语素“无量”语义风格不合，不能组合为“很多无量”。"
    },
    {
      "word": "无数",
      "explanation": "“无数”表示不可计数，常作定语修饰具体名词（如“无数星星”），与“无量”构成词义冗余，不能直接作其常规固定搭配。"
    }
  ],
  "collocation_wrong_collocate": "面积无量",
  "cloze_distractors": [
    {
      "word": "无限",
      "explanation": "“无限”强调没有边界限制，虽然意思接近，但在成语“前途无量”中不可替换为“前途无限”（习惯上常用“前途无量”）。"
    },
    {
      "word": "无尽",
      "explanation": "“无尽”侧重于没有穷尽、没有终点，多形容思念、苦难等抽象情感或时间，修饰前途属于语域错配。"
    },
    {
      "word": "微薄",
      "explanation": "“微薄”意为微小单薄，与“无量”语义完全相反，放在褒奖语境中语义自相矛盾。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "桌子上放着无量的苹果，大家可以随便吃。",
      "explanation": "“无量”属于书面语且形容极其宏大或不可估量的抽象事物（如功德、前途），不能直接作定语修饰具体、有限的可数生活实物。"
    },
    {
      "sentence": "他今天无量地喝了三杯水。",
      "explanation": "“无量”是形容词，不能直接充当修饰具体动作频次或数量的状语，句法功能错误。"
    },
    {
      "sentence": "这个水杯很无量，能装一升水。",
      "explanation": "“无量”表示不可限量，不能用来描述容量确切、有限的具体容器体积。"
    }
  ],
  "spot_incorrect": {
    "sentence": "这家公司为了谋取暴利生产假药，真是功德无量。",
    "error_description": "“功德无量”是极高的褒义词，用于形容造福众生的善行，不能用于批判作恶造假的企业，属于褒贬误用。",
    "corrected_sentence": "这家公司为了谋取暴利生产假药，真是罪大恶极。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    {
      "fake_form": "无量化",
      "explanation": "错误借用后缀“-化”企图构成动词，现代汉语中不存在“无量化”这一构词。"
    },
    {
      "fake_form": "无量性",
      "explanation": "错误借用抽象名词后缀“-性”构成生造词，汉语中通常用“不可限量”或“无限性”，无“无量性”用法。"
    },
    {
      "fake_form": "无量度",
      "explanation": "错误杂糅“无量”与物理测量名词“量度”，汉语中并无此衍生复合词。"
    }
  ],
